```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract SafeGalaxyCoin is ERC20, Ownable {
    uint256 private constant LOCK_PERIOD = 365 days; // 1 year
    uint256 private constant LIQUIDITY_POOL_THRESHOLD = 1e6 ether; // 1 million wei

    constructor() ERC20("SafeGalaxyCoin", "SGC") {
        _mint(msg.sender, 1000000 * 10**decimals()); // Mint 1 million tokens
    }

    modifier onlyAfterLockPeriod() {
        require(block.timestamp >= block.timestamp + LOCK_PERIOD, "Lock period not over");
        _;
    }

    function mint(address to, uint256 amount) public onlyOwner {
        _mint(to, amount);
    }

    function burn(address from, uint256 amount) public onlyOwner {
        _burn(from, amount);
    }

    function emergencyWithdraw() public onlyOwner {
        require(address(this).balance >= LIQUIDITY_POOL_THRESHOLD, "Liquidity pool threshold not met");
        payable(owner()).transfer(address(this).balance);
    }

    function transfer(address recipient, uint256 amount) public override onlyAfterLockPeriod returns (bool) {
        return super.transfer(recipient, amount);
    }

    function transferFrom(address sender, address recipient, uint256 amount) public override onlyAfterLockPeriod returns (bool) {
        return super.transferFrom(sender, recipient, amount);
    }
}
```

